sys_script.script:
(function executeRule(current, previous /* null when async */) {


    /* ======================================================
       CLAIM ANSWERS
    ====================================================== */

    var answer1 =
        current.getValue(
            'u_claimant_answer_1'
        );

    var answer2 =
        current.getValue(
            'u_claimant_answer_2'
        );

    var answer3 =
        current.getValue(
            'u_claimant_answer_3'
        );



    /* ======================================================
       DO NOT RE-RUN VERIFICATION ON UNRELATED UPDATES

       This prevents admin/lifecycle updates from
       recalculating Pass / Review / Fail again.
    ====================================================== */

    var answersChanged =
        current.operation() === 'insert' ||

        current
            .getElement(
                'u_claimant_answer_1'
            )
            .changes() ||

        current
            .getElement(
                'u_claimant_answer_2'
            )
            .changes() ||

        current
            .getElement(
                'u_claimant_answer_3'
            )
            .changes();


    if (
        !answersChanged
    ) {

        return;

    }



    /* ======================================================
       NO ANSWERS YET

       Claim widget initially inserts the Claim before
       saving the answers.
    ====================================================== */

    if (
        !answer1 &&
        !answer2 &&
        !answer3
    ) {

        current.setValue(
            'u_verification_result',
            'pending'
        );


        return;

    }



    /* ======================================================
       RUN TASK 18 SEMANTIC OWNERSHIP VERIFICATION
    ====================================================== */

    var verifier =
        new CampusMatchClaimVerification();


    var result =
        verifier.verifyClaim(
            current
        );



    /* ======================================================
       SAVE INDIVIDUAL SIMILARITY SCORES

       Support either u_ field names or scoped names.
    ====================================================== */

    function setSimilarity(
        candidates,
        value
    ) {

        var fieldName = '';


        for (
            var i = 0;
            i < candidates.length;
            i++
        ) {

            if (
                current.isValidField(
                    candidates[i]
                )
            ) {

                fieldName =
                    candidates[i];

                break;

            }

        }


        if (!fieldName) {

            return;

        }


        if (
            value === null ||
            value === undefined ||
            value === ''
        ) {

            current.setValue(
                fieldName,
                ''
            );

        }
        else {

            current.setValue(
                fieldName,
                value
            );

        }

    }



    setSimilarity(
        [
            'u_verification_similarity_1',
            'verification_similarity_1'
        ],
        result.similarity1
    );


    setSimilarity(
        [
            'u_verification_similarity_2',
            'verification_similarity_2'
        ],
        result.similarity2
    );


    setSimilarity(
        [
            'u_verification_similarity_3',
            'verification_similarity_3'
        ],
        result.similarity3
    );



    /* ======================================================
       SAVE OVERALL SCORE
    ====================================================== */

    current.setValue(
        'u_verification_score',
        result.score
    );



    /* ======================================================
       SAVE PASS / REVIEW / FAIL
    ====================================================== */

    current.setValue(
        'u_verification_result',
        result.result
    );


})(current, previous);
